<?php
declare(strict_types=1);
namespace TempNumber;
require __DIR__.'/../src/bootstrap.php';$name=$argv[1]??'';$file=$argv[2]??'';$allowed=['getatext_pricing','5sim_pricing','long-term_pricing','dedicated_pricing','smm_pricing','rewards'];if(!in_array($name,$allowed,true)||!is_file($file)){fwrite(STDERR,"Usage: php bin/configure.php <setting-name> <json-file>\nAllowed: ".implode(', ',$allowed)."\n");exit(1);}try{$value=json_decode(file_get_contents($file),true,32,JSON_THROW_ON_ERROR);if(!is_array($value))throw new \RuntimeException('Use a JSON object.');foreach($value as$key=>$entry)if(preg_match('/cents|basis_points|threshold|numerator|denominator/',$key)&&(!is_int($entry)||$entry<0))throw new \RuntimeException('Non-negative integer required for '.$key);if($name!=='rewards'){foreach(['currency','fx_numerator','fx_denominator','fx_updated_at']as$key)if(empty($value[$key]))throw new \RuntimeException('Missing '.$key);if(!preg_match('/^[A-Z]{3}$/D',$value['currency']))throw new \RuntimeException('Use an ISO currency code.');}tx(function()use($name,$value){query('DELETE FROM settings WHERE name=?',[$name]);query('INSERT INTO settings (name,value,updated_at) VALUES (?,?,?)',[$name,json_encode($value),now()]);audit('commercial_setting_updated',null,['name'=>$name]);});echo "Configuration saved.\n";}catch(\Throwable $e){fwrite(STDERR,$e->getMessage()."\n");exit(1);}
